			function ss(v, i) { return ((v[i] & 127) << 21) | ((v[i + 1] & 127) << 14) | ((v[i + 2] & 127) << 7) | (v[i + 3] & 127); }
			function a4(v, i) { return String.fromCharCode(v[i], v[i + 1], v[i + 2], v[i + 3]); }
