						if (!/[A-Z]/.test(id[0])) break;
						const fsize = ver === 4 ? ss(v, off + 4) : ((v[off + 4] << 24) | (v[off + 5] << 16) | (v[off + 6] << 8) | v[off + 7]);
						if (fsize <= 0 || off + 10 + fsize > v.length) break;
