		// ═══════════ 8.9 可拖动工具条（毛玻璃长条，位置记忆）═══════════
		function startDock() {
			const dock = document.createElement("div");
			dock.className = "ff-dock";
			document.body.appendChild(dock);

			const LS_DOCK = "ff_dock_pos";
